:root{--text-color: rgb(34, 34, 34);--text-color-disabled: rgb(153, 153, 153);--page-bg-color: rgb(245, 245, 245);--primary-color: rgb(102, 51, 204);--secondary-color: rgb(0, 187, 115);--primary-color-light: rgb(226, 215, 249);--secondary-color-light: rgb(188, 245, 224)}.m-chckbox--container{position:relative;display:inline-flex;align-items:center;line-height:20px;cursor:pointer}.m-chckbox--label{position:relative;padding-left:.5em;cursor:pointer}.m-chckbox--group{position:relative;box-sizing:border-box;width:20px;height:20px;border:2px solid rgba(0,0,0,.54);border-radius:2px;transition:.4s cubic-bezier(0.25, 0.8, 0.25, 1)}.m-chckbox--group input[type=checkbox]{position:absolute;left:-999rem;-webkit-appearance:none;appearance:none}.m-chckbox--container.active .m-chckbox--group{background-color:var(--primary-color);border-color:var(--primary-color)}.m-chckbox--container.disabled{cursor:not-allowed}.m-chckbox--container.disabled .m-chckbox--group{opacity:.14}.m-chckbox--container.disabled .m-chckbox--label{cursor:not-allowed;opacity:.24}